import type { ImageLoaderProps } from "next/image";
import { variantUrl } from "./imageVariants.mjs";

// Custom next/image loader: serves the variants pre-generated by
// scripts/image-variants.ts as static files, instead of resizing through
// /_next/image (which runs the Worker for every image request).
export default function imageLoader({ src, width }: ImageLoaderProps): string {
  // next dev serves originals; the query keeps next/image's width check quiet
  if (process.env.NODE_ENV === "development") {
    return `${src}${src.includes("?") ? "&" : "?"}w=${width}`;
  }
  return variantUrl(src, width) ?? src;
}
